INSERT INTO `announcements` (`id`, `uuid`, `school_id`, `branch_id`, `title`, `content`, `slug`, `feature_image`, `view_count`, `status`, `publish_at`, `expire_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES
(1, 'ed77ca22-9aa5-45b6-8623-8af15ad5f66f', 1, NULL, 'Welcome to Skoolyst – A Digital Platform for Schools to Showcase Their Profiles and Announcements', '<p>We’re excited to introduce <strong>Skoolyst</strong> — a dedicated platform designed <strong>for schools like yours</strong>!<br>Now, your school can easily <strong>create a profile, showcase achievements, and share announcements</strong> with parents, students, and the community.</p>\n\n<p>✅ Create and manage your school profile<br>✅ Post important updates and announcements<br>✅ Connect with your audience in one place</p>\n\n<p>Join <strong>Skoolyst</strong> today and let the world see what makes your school special!<br><br>👉 <a href=\"https://skoolyst.com/\">https://skoolyst.com/</a></p>', 'welcome-to-skoolyst-a-digital-platform-for-schools-to-showcase-their-profiles-and-announcements-oQ2UgL', 'school/skoolyst/announcements/wiSABf7gPqyJdIQdapepbDQWpLFq2EXhLGpG3Lnd.jpg', 14, 'published', '2025-11-13 00:24:00', '2025-11-17 00:24:00', '📢 Hello Schools! Welcome to Skoolyst 🎓', 'Discover Skoolyst, an innovative platform where schools can create profiles, share updates, and publish announcements to connect with students, parents, and the community. Join today and showcase your school to the world!', '2025-11-13 14:25:08', '2026-02-24 21:25:59');
