ranch\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:8:\"branches\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:20:{s:2:\"id\";i:11;s:9:\"school_id\";i:22;s:4:\"name\";s:25:\"Pre-School Campus Clifton\";s:7:\"address\";s:65:\"Plot St:# 22 Marine Promenade Block-1, Clifton, Karachi, Pakistan\";s:4:\"city\";s:7:\"Karachi\";s:14:\"contact_number\";s:14:\"021-34166250-1\";s:16:\"branch_head_name\";s:32:\"Zainab Rangwala (Vice Principal)\";s:11:\"description\";s:618:\"Ideally situated in Clifton Block 1, Main Marine Promenade Road, with a picturesque view of the sea. This pre-school offers thoughtfully designed, spacious classrooms supported by two experienced teachers in every class, ensuring individual attention for each child. The campus features a Reggio Emilia-inspired Early Years Foundation Stage (EYFS) curriculum with inquiry-based learning. The Parents as Partners programme engages parents as active participants in their child\'s learning. The campus includes art room, mud kitchen, auditorium, outside play area, rooftop, music room, library, and water play facilities.\";s:11:\"school_type\";N;s:13:\"fee_structure\";N;s:11:\"curriculums\";s:40:\"Cambridge, EYFS (Reggio Emilia-inspired)\";s:7:\"classes\";s:75:\"Playgroup, Reception, Prep I, Prep II (1 year 7 months to 5 years 3 months)\";s:14:\"images_gallery\";N;s:8:\"features\";N;s:8:\"latitude\";N;s:9:\"longitude\";N;s:14:\"is_main_branch\";i:0;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:19:\"2026-06-26 12:46:23\";s:10:\"updated_at\";s:19:\"2026-06-26 12:46:23\";}s:11:\"\0*\0original\";a:20:{s:2:\"id\";i:11;s:9:\"school_id\";i:22;s:4:\"name\";s:25:\"Pre-School Campus Clifton\";s:7:\"address\";s:65:\"Plo