he\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:16:{i:0;s:9:\"school_id\";i:1;s:4:\"name\";i:2;s:7:\"address\";i:3;s:4:\"city\";i:4;s:14:\"contact_number\";i:5;s:16:\"branch_head_name\";i:6;s:11:\"description\";i:7;s:11:\"school_type\";i:8;s:13:\"fee_structure\";i:9;s:11:\"curriculums\";i:10;s:7:\"classes\";i:11;s:8:\"latitude\";i:12;s:9:\"longitude\";i:13;s:14:\"is_main_branch\";i:14;s:6:\"status\";i:15;s:8:\"features\";}s:10:\"\0*\0guarded\";a:1:{i:0;s:1:\"*\";}}i:5;O:17:\"App\\Models\\Branch\":33:{s:13:\"\0*\0connection\";s:5:\"mysql\";s:8:\"\0*\0table\";s:8:\"branches\";s:13:\"\0*\0primaryKey\";s:2:\"id\";s:10:\"\0*\0keyType\";s:3:\"int\";s:12:\"incrementing\";b:1;s:7:\"\0*\0with\";a:0:{}s:12:\"\0*\0withCount\";a:0:{}s:19:\"preventsLazyLoading\";b:0;s:10:\"\0*\0perPage\";i:15;s:6:\"exists\";b:1;s:18:\"wasRecentlyCreated\";b:0;s:28:\"\0*\0escapeWhenCastingToString\";b:0;s:13:\"\0*\0attributes\";a:20:{s:2:\"id\";i:16;s:9:\"school_id\";i:22;s:4:\"name\";s:36:\"Senior Heritage Campus (Civil Lines)\";s:7:\"address\";s:49:\"8th Flench Street, Civil Lines, Karachi, Pakistan\";s:4:\"city\";s:7:\"Karachi\";s:14:\"contact_number\";s:12:\"021-37235239\";s:16:\"branch_head_name\";s:24:\"Shams Samson (Principal)\";s:11:\"description\";s:897:\"The Heritage campus is located centrally in Civil Lines and easily accessible from several central points of the city. This stunning, one-of-a-kind Heritage property from the early 20th century has been complemented with a large purpose-built new wing housing additional well-lit air-conditioned classrooms, a lecture theatre, multipurpose halls, an art studio, computer laboratory, and two Cambridge-approved science laboratories.\r\n\r\nThe Middle Years (Grades 6-8) build a strong foundation for Cambridge IGCSE and GCE O Levels with personalized learning. The Senior Years (Grades 9-11) follow the renowned Cambridge IGCSE and GCE O Levels curriculum. Students consistently attain outstanding academic results with multiple Top in the World and Top in Pakistan awards. Facilities include art room, basketball court, cafeteria, IT lab, lecture theatre, multipurpose room, library, and science labs.\";s:11:\"school_type\";s:12:\"co-education\";s:13:\"fee_structure\";N;s:11:\"curriculums\";s:25:\"Cambridge, IGCSE, O-Level\";s:7:\"classes\";s:48:\"Grade 6 to 11 (O Levels/IGCSE), Ages 11-16 years\";s:14:\"images_gallery\";N;s:8:\"features\";s:55:\"[\"1\",\"4\",\"5\",\"6\",\"7\",\"8\",\"10\",\"11\",\"12\",\"13\",\"14\",\"15\"]\";s:8:\"latitude\";N;s:9:\"longitude\";N;s:14:\"is_main_branch\";i:0;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:19:\"2026-06-26 15:22:30\";s:10:\"updated_at\";s:19:\"2026-06-26 15:22:30\";}s:11:\"\0*\0original\";a:20:{s:2:\"id\";i:16;s:9:\"school_id\";i:22;s:4:\"name\";s:36:\"Senior Heritage Campus (Civil Lines)\";s:7:\"address\";s:49:\"8th Flench Street, Civil Lines, Karachi, Pakistan\";s:4:\"city\";s:7:\"Karachi\";s:14:\"contact_number\";s:12:\"021-37235239\";s:16:\"branch_head_name\";s:24:\"Shams Samson (Principal)\";s:11:\"description\";s:897:\"The Heritage campus is located centrally in Civil Lines and easily accessible from several central points of the city. This stunning, one-of-a-kind Heritage property from the early 20th century has been complemented with a large purpose-built new wing housing additional well-lit air-conditioned classrooms, a lecture theatre, multipurpose halls, an art studio, computer laboratory, and two Cambridge-approved science laboratories.\r\n\r\nThe Middle Years (Grades 6-8) build a strong foundation for Cambridge IGCSE and GCE O Levels with personalized learning. The Senior Years (Grades 9-11) follow the renowned Cambridge IGCSE and GCE O Levels curriculum. Students consistently attain outstanding academic results with multiple Top in the World and Top in Pakistan awards. Facilities include art room, basketball court, cafeteria, IT lab, lecture theatre, multipurpose room, library, and science labs.\";s:11:\"school_type\";s:12:\"co-education\";s:13:\"fee_structure\";N;s:11:\"curriculums\";s:25:\"Cambridge, IGCSE, O-Level\";s:7:\"classes\";s:48:\"Grade 6 to 11 (O Levels/IGCSE), Ages 11-16 years\";s:14:\"images_gallery\";N;s:8:\"features\";s:55:\"[\"1\",\"4\",\"5\",\"6\",\"7\",\"8\",\"10\",\"11\",\"12\",\"13\",\"14\",\"15\"]\";s:8:\"latitude\";N;s:9:\"longitude\";N;s:14:\"is_main_branch\";i:0;s:6:\"status\";s:6:\"active\";s:10:\"created_at\";s:19:\"2026-06-26 15:22:30\";s:10:\"updated_at\";s:19:\"2026-06-26 15:22:30\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0previous\";a:0:{}s:8:\"\0*\0casts\";a:6:{s:14:\"is_main_branch\";s:7:\"boolean\";s:8:\"latitude\";s:9:\"decimal:8\";s:9:\"longitude\";s:9:\"decimal:8\";s:8:\"features\";s:5:\"array\";s:11:\"school_type\";s:26:\"App\\Enums\\SchoolGenderType\";s:6:\"status\";s:22:\"App\\Enums\\ActiveStatus\";}s:17:\"\0*\0classCastCache\";a:0:{}s:21:\"\0*\0attributeCastCache\";a:0:{}s:13:\"\0*\0dateFormat\";N;s:10:\"\0*\0appends\";a:0:{}s:19:\"\0*\0dispatchesEvents\";a:0:{}s:14:\"\0*\0observables\";a:0:{}s:12:\"\0*\0relations\";a:0:{}s:10:\"\0*\0touches\";a:0:{}s:27:\"\0*\0relationAutoloadCallback\";N;s:26:\"\0*\0relationAutoloadContext\";N;s:10:\"timestamps\";b:1;s:13:\"usesUniqueIds\";b:0;s:9:\"\0*\0hidden\";a:0:{}s:10:\"\0*\0visible\";a:0:{}s:11:\"\0*\0fillable\";a:16:{i:0;s:9:\"school_id\";i:1;s:4:\"name\";i:2;s:7:\"address\";i:3;s:4:\"city\";i:4;s:14:\"contact_number\";i:5;s:16:\"branch_head_name\";i:6;s:11:\"description\";i:7;s:11:\"school_type\";i:8;s:13:\"fee_structure\";i:9;s:11:\"curriculums\";i:10;s:7:\"classes\";i:11;s:8:\"latitude\";i:12;s:9:\"longitude\";i:13;s:14:\"is_main_