(11, 'df75c40a-0e0b-4344-a60b-b16e02c1b940', 11, 8, 'After processing, data becomes:', 'single', '\"{\\\"1\\\":\\\"Numbers\\\",\\\"2\\\":\\\"Information\\\",\\\"3\\\":\\\"Storage\\\",\\\"4\\\":\\\"Input\\\"}\"', '\"[\\\"2\\\"]\"', NULL, NULL, 'medium', NULL, 1, 0, NULL, NULL, NULL, 0, 0, 'published', 1, NULL, NULL, '2026-03-10 03:07:25', '2026-03-10 03:07:25'),
(12, '43bc7d77-e613-4f7c-8b9c-9980cd3c6333', 11, 8, 'The physical parts of a computer are called:', 'single', '\"{\\\"1\\\":\\\"Software\\\",\\\"2\\\":\\\"Hardware\\\",\\\"3\\\":\\\"Data\\\",\\\"4\\\":\\\"Programs\\\"}\"', '\"[\\\"2\\\"]\"', NULL, NULL, 'medium', NULL, 1, 0, NULL, NULL, NULL, 0, 0, 'published', 1, NULL, NULL, '2026-03-10 03:10:00', '2026-03-10 03:10:00'),
