(2356, 'a0277c4d-3010-4418-8973-7d7efce2677e', 149, 4, 'To \'cut corners\' means to:', 'single', '\"{\\\"1\\\":\\\"trim paper\\\",\\\"2\\\":\\\"take a long route\\\",\\\"3\\\":\\\"do something cheaply or carelessly\\\",\\\"4\\\":\\\"be very careful\\\"}\"', '\"[\\\"3\\\"]\"', '\'To cut corners\' means to do something cheaply or carelessly to save time or money.', 'Skimp to save effort.', 'easy', NULL, 1, 0, '\"[\\\"money\\\",\\\"cut-corners\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '5', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2357, '62186b18-b9c1-497a-930e-1f597171f0cd', 149, 4, 'The phrasal verb \'give up\' means to:', 'single', '\"{\\\"1\\\":\\\"donate\\\",\\\"2\\\":\\\"lift something\\\",\\\"3\\\":\\\"surrender a seat\\\",\\\"4\\\":\\\"quit \\\\\\/ stop trying\\\"}\"', '\"[\\\"4\\\"]\"', '\'Give up\' means to quit or stop trying.', 'Stop trying.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"give-up\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2358, '4932430e-6aba-4868-9bff-620e94534871', 149, 4, '\'Look after\' someone means to:', 'single', '\"{\\\"1\\\":\\\"take care of them\\\",\\\"2\\\":\\\"search for them\\\",\\\"3\\\":\\\"investigate them\\\",\\\"4\\\":\\\"follow them\\\"}\"', '\"[\\\"1\\\"]\"', '\'Look after\' means to take care of; \'look into\' means to investigate.', 'Care for them.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"look-after\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2359, 'd3d074b7-e80b-4f31-941f-a704bff00d2c', 149, 4, '\'Look into\' a matter means to:', 'single', '\"{\\\"1\\\":\\\"take care of it\\\",\\\"2\\\":\\\"investigate it\\\",\\\"3\\\":\\\"stare at it\\\",\\\"4\\\":\\\"anticipate it\\\"}\"', '\"[\\\"2\\\"]\"', '\'Look into\' means to investigate; \'look after\' means to care for.', 'Investigate it.', 'medium', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"look-into\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2360, '95fe43f9-97f7-47f5-934b-bcc2021db4bf', 149, 4, '\'Look forward to\' something means to:', 'single', '\"{\\\"1\\\":\\\"dread it\\\",\\\"2\\\":\\\"investigate it\\\",\\\"3\\\":\\\"anticipate it with pleasure\\\",\\\"4\\\":\\\"care for it\\\"}\"', '\"[\\\"3\\\"]\"', '\'Look forward to\' means to anticipate something with pleasure.', 'Eagerly await.', 'medium', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"look-forward\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2361, '7b99d2d8-d771-4e64-ab2a-8098ff5986bb', 149, 4, 'To \'put off\' an event means to:', 'single', '\"{\\\"1\\\":\\\"cancel it forever\\\",\\\"2\\\":\\\"attend it\\\",\\\"3\\\":\\\"enjoy it\\\",\\\"4\\\":\\\"postpone it\\\"}\"', '\"[\\\"4\\\"]\"', '\'Put off\' means to postpone something to a later time.', 'Delay it.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"put-off\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2362, '1b1b3893-26a6-4199-a567-ec1eaf639222', 149, 4, 'To \'put up with\' something means to:', 'single', '\"{\\\"1\\\":\\\"tolerate it\\\",\\\"2\\\":\\\"build it\\\",\\\"3\\\":\\\"reject it\\\",\\\"4\\\":\\\"raise it high\\\"}\"', '\"[\\\"1\\\"]\"', '\'Put up with\' means to tolerate or endure something.', 'Bear it patiently.', 'medium', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"put-up-with\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
