(2364, '04f08959-06b5-4353-9d17-54f3dc832e3c', 149, 4, 'When a machine \'breaks down\', it:', 'single', '\"{\\\"1\\\":\\\"is sold\\\",\\\"2\\\":\\\"speeds up\\\",\\\"3\\\":\\\"stops functioning \\\\\\/ collapses\\\",\\\"4\\\":\\\"is repaired\\\"}\"', '\"[\\\"3\\\"]\"', '\'Break down\' means to stop functioning or collapse.', 'Stops working.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"break-down\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2365, 'e858f67c-9724-4228-97d9-0bf40c98de3d', 149, 4, 'To \'bring up\' a child means to:', 'single', '\"{\\\"1\\\":\\\"carry them\\\",\\\"2\\\":\\\"wake them\\\",\\\"3\\\":\\\"scold them\\\",\\\"4\\\":\\\"raise them\\\"}\"', '\"[\\\"4\\\"]\"', '\'Bring up\' means to raise a child (or to mention a topic).', 'Raise / rear.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"bring-up\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2366, '74705398-24e2-404c-9727-b1677a489bee', 149, 4, 'To \'turn down\' an offer means to:', 'single', '\"{\\\"1\\\":\\\"reject it\\\",\\\"2\\\":\\\"lower the volume\\\",\\\"3\\\":\\\"accept it\\\",\\\"4\\\":\\\"fold it\\\"}\"', '\"[\\\"1\\\"]\"', '\'Turn down\' means to reject or refuse; \'turn up\' means to arrive.', 'Refuse it.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"turn-down\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2367, '3c4f3886-5774-449e-80fe-3ece4c56bbef', 149, 4, 'To \'turn up\' means to:', 'single', '\"{\\\"1\\\":\\\"reject\\\",\\\"2\\\":\\\"arrive \\\\\\/ appear\\\",\\\"3\\\":\\\"increase volume\\\",\\\"4\\\":\\\"fold over\\\"}\"', '\"[\\\"2\\\"]\"', '\'Turn up\' means to arrive or appear; \'turn down\' means to reject.', 'Show up.', 'easy', NULL, 1, 0, '\"[\\\"phrasal\\\",\\\"turn-up\\\",\\\"confusable\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '6', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
