(2369, '4c8cfaed-afb0-4830-8ba9-f3a55fa8c8c2', 149, 4, 'The phrase \'in spite of\' means:', 'single', '\"{\\\"1\\\":\\\"because of\\\",\\\"2\\\":\\\"instead of\\\",\\\"3\\\":\\\"in favour of\\\",\\\"4\\\":\\\"despite \\\\\\/ regardless of\\\"}\"', '\"[\\\"4\\\"]\"', '\'In spite of\' means despite or regardless of.', 'Despite it.', 'medium', NULL, 1, 0, '\"[\\\"prepositional\\\",\\\"in-spite-of\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '7', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
(2370, '98ae201d-204b-4f72-b99d-7814d82b0d65', 149, 4, '\'On behalf of\' means:', 'single', '\"{\\\"1\\\":\\\"representing \\\\\\/ for\\\",\\\"2\\\":\\\"against\\\",\\\"3\\\":\\\"instead of paying\\\",\\\"4\\\":\\\"behind\\\"}\"', '\"[\\\"1\\\"]\"', '\'On behalf of\' means representing or acting for someone.', 'Speaking for someone.', 'medium', NULL, 1, 0, '\"[\\\"prepositional\\\",\\\"on-behalf-of\\\"]\"', 'English Vocabulary: Idioms & Phrases (Complete Notes)', '7', 0, 0, 'published', 1, NULL, NULL, '2026-06-03 05:01:50', '2026-06-03 05:01:50'),
