INSERT INTO `products` (`id`, `uuid`, `shop_id`, `category_id`, `school_id`, `association_id`, `name`, `slug`, `sku`, `description`, `short_description`, `product_type`, `brand`, `material`, `color`, `size`, `base_price`, `sale_price`, `cost_price`, `profit_margin`, `stock_quantity`, `low_stock_threshold`, `manage_stock`, `is_in_stock`, `is_featured`, `is_active`, `is_approved`, `meta_title`, `meta_description`, `meta_keywords`, `main_image_url`, `image_gallery`, `created_at`, `updated_at`) VALUES
(1, '05839c95-0f48-407c-b467-0b762188cb0c', 1, 2, NULL, NULL, 'M&G Active Stapler MGS-16', 'mg-active-stapler-mgs-16', 'MGS-16-BLUE', 'The M&G Active MGS-16 Stapler is designed for long-lasting performance with its full steel mechanism and durable metal leaf spring. It provides smooth stapling and is suitable for everyday use in schools, offices, shops, and homes. The stapler supports both 24/6 and 26/6 size staples, making it versatile for various paper-binding needs. Its compact, ergonomic blue design ensures comfortable handling and reliable operation.', 'Durable M&G steel-body stapler with a strong metal leaf spring, compatible with 24/6 and 26/6 staples. Ideal for school, office, and home use.', 'stationery', 'M&G', 'Steel Mechanism + Hard ABS Plastic Body', 'Blue', 'Compatible with 24/6 and 26/6 staples', 670.00, NULL, NULL, NULL, 40, 5, 1, 1, 0, 1, 1, NULL, NULL, NULL, 'products/1/main/9aDazpl4AqabzbK1YpTo6xKXC6dCyXVsTRPONmKG.jpg', NULL, '2025-12-01 14:46:31', '2025-12-02 13:34:37'),
(2, '29a7ca13-2b2d-4d22-ac39-e9e636d8dcd2', 1, 2, NULL, NULL, 'FUJI T-35 Desktop Stapler', 'fuji-t-35-desktop-stapler', 'FUJI-T35-STPLR', 'The FUJI T-35 Stapler is a high-quality, lightweight, and ergonomic stapler built for consistent performance. Its sturdy plastic and metal construction ensures long-term durability, while the comfortable grip design makes it easy to use for extended periods.\r\nCompatible with standard 24/6 and 26/6 staples, this stapler is ideal for binding papers in offices, classrooms, shops, and home workspaces.\r\nPerfect for students, teachers, office workers, and businesses needing a reliable day-to-day stapling solution.', 'A compact and durable stapler designed for everyday office, school, and home use. Supports both 24/6 and 26/6 staple sizes, offering smooth and reliable stapling performance.', 'stationery', 'FUJI', 'Plastic (body) + Metal', 'Black top with Beige base', 'Medium / Standard', 400.00, 400.00, 380.00, 5.26, 500, 5, 1, 1, 0, 1, 1, NULL, NULL, NULL, 'products/2/main/b7c9aee5-2afe-427a-88b6-3d9f1a53c0a3.webp', '[\"products\\/2\\/gallery\\/be07c399-8285-4f37-a916-5fcce1b86287.webp\",\"products\\/2\\/gallery\\/95e99495-5b8c-45d3-99b8-efa69cd0f934.webp\"]', '2025-12-02 13:33:29', '2026-07-03 13:32:32'),
(3, 'adcc1067-f66d-4cde-98e4-567b933c87ba', 2, 1, NULL, NULL, 'Dollar Pointer WOW Black [IS][1PC]', 'dollar-pointer-wow-black-is1pc', 'SKU-693099F4AEED0', 'Dollar Pointer WOW Black [IS][1PC]\r\n[U30-01-11-03-25]\r\n \r\n\r\nGive your writing a WOW factor !\r\nFeatures a specially engineered 0.3mm tip to ensure smooth ink flow for extra smooth writing. Floats on the paper for an incredibly neat writing experience. Iconic design with an excellent body makes it the most practical writing tool for people from all walks of life. Ultra smooth ink that ensures comfortable lengthy writing without skipping or smudging. Available in 9 brilliant colors (Blue, Black, Red, Green, Lilac, Turquoise, Pink, Brown & Orange). Considered to be the best fine liner in Pakistan that provides precise and smooth writing in the most convenient and revocable way.\r\n\r\n\r\n\r\n0.3 mm Tip Pointer / Fine liner\r\nRecyclable PP Material\r\nMade in Pakistan\r\nColors : Black, Blue, Red, Green, Turquoise, Pink, Lilac, Brown, Orange\r\nSingle Color Pack\r\n10 Pointers in a pack', '0.3 mm Tip Pointer / Fine liner\r\nRecyclable PP Material\r\nMade in Pakistan\r\nColors : Black, Blue, Red, Green, Turquoise, Pink, Lilac, Brown, Orange\r\nSingle Color Pack\r\n10 Pointers in a pack', 'other', 'Dollar', 'Plastic', 'Black', '6 Inches', 30.00, 45.00, 25.00, 20.00, 56, 5, 1, 1, 0, 1, 1, NULL, NULL, NULL, 'products/3/main/UkzIBM3JXP7JuY8HcyvEbf4gejhQaoj7tcSApF6s.jpg', '[\"products\\/3\\/gallery\\/mArE6tKqSVqWSH6OFGpXYJkT6ET15HXGaw7h9RoV.jpg\"]', '2025-12-03 15:13:40', '2025-12-03 15:16:59'),
(4, 'f2eb660f-7488-4a04-8b4b-c790d5551212', 1, 5, NULL, NULL, 'Amythe School Backpack for Girls', 'amythe-school-backpack-for-girls', 'backpack-0004', 'DISCOVER THE ULTIMATE ELEGANCE AND COMFORT WITH GIRLS SCHOOL BAGS\r\n \r\n\r\nThe World Leader In Vibrant Educational Gear. From Tough Impact-resistant Princess Designs To Reinforced Multi-compartment Layouts, Our Collection At Kashif Luggage & Bags Offers The Ultimate Durability And Charming Style For Every Journey.\r\nKarachi 2 Hour Express Delivery Available On All Prepaid Orders!\r\n\r\nkashifluggage.com/collections/girls-school-bags/products/amythe-school-backpack\r\nor \r\nkashifluggage.com/collections/girls-school-bags?srsltid=AfmBOorslRsWMrTewNcAhLG0ir5Hmuhk7-FVX78Ean45wWnYjesNQhTX', 'A stylish and practical backpack designed for school-going girls, featuring a spacious main compartment that easily fits books, a laptop, and other school essentials. With its fashionable plaid pattern and soft pink tones, it\'s perfect for teenage girls who want both function and style. Multiple pockets keep accessories and personal items neatly organized, while the adjustable, padded straps and cushioned back ensure a comfortable, all-day carry.', 'bag', 'Princess', 'Polyester', 'Pink', 'Suitable for: Grade 3 to Grade 8', 3000.00, 3100.00, 3000.00, 0.00, 10, 5, 1, 1, 0, 1, 1, NULL, NULL, NULL, 'products/4/main/558e31bc-3e91-4805-bc0c-0f5ceaffa0fa.webp', '[\"products\\/4\\/gallery\\/5dda9ca1-cf08-4bb4-be44-1a335edde9e1.webp\",\"products\\/4\\/gallery\\/1e8d4971-85ba-4f58-b63f-0cf194899ae8.webp\",\"products\\/4\\/gallery\\/6560820d-9a94-4294-8c2e-da9f4b5ef3d9.webp\"]', '2026-07-02 17:58:34', '2026-07-02 17:59:08'),
(5, '8cd8e5a5-93fd-4d8e-ac38-3ac85f843b6c', 1, 8, NULL, NULL, 'Dollar My Pencil 666 Wooden Lead Pencils (Pack of 12)', 'dollar-my-pencil-666-wooden-lead-pencils-pack-of-12', 'jj0004', 'Dollar My Pencil Wooden Lead Pencils (Model 666) offer excellent writing quality with soft, smooth lead that\'s easy to sharpen. Made with pure, non-toxic lead material, these pencils are safe for students of all ages. Perfect for everyday school use, office work, and sketching/drawing. Each pack contains 12 durable wooden pencils, trusted by students across Pakistan for reliable, reasonable-priced writing. - \r\nhttps://www.daraz.pk/products/my-pencil-lead-666-dolar-wooden-pack-of-12-pencils-i373131973-s1847308047.html?c=&channelLpJumpArgs=&clickTrackInfo=query%253Aleads%252Bpencil%253Bnid%253A373131973%253Bsrc%253ALazadaMainSrp%253Brn%253A052e0de6f2d8428c080a8c884d06cf9e%253Bregion%253Apk%253Bsku%253A373131973_PK%253Bprice%253A220%253Bclient%253Adesktop%253Bsupplier_id%253A1077734%253Bsession_id%253A%253Bbiz_source%253Ah5_external%253Bslot%253A2%253Butlog_bucket_id%253A470687%253Basc_category_id%253A10000648%253Bitem_id%253A373131973%253Bsku_id%253A1847308047%253Bshop_id%253A189350%253BtemplateInfo%253A&freeshipping=0&fs_ab=1&fuse_fs=&lang=en&location=Punjab&price=2.2E%202&priceCompare=skuId%3A1847308047%3Bsource%3Alazada-search-voucher%3Bsn%3A052e0de6f2d8428c080a8c884d06cf9e%3BoriginPrice%3A22000%3BdisplayPrice%3A22000%3BisGray%3Afalse%3BsinglePromotionId%3A-1%3BsingleToolCode%3A-1%3BvoucherPricePlugin%3A0%3Btimestamp%3A1783073093214&ratingscore=4.714285714285714&request_id=052e0de6f2d8428c080a8c884d06cf9e&review=28&sale=117&search=1&source=search&spm=a2a0e.searchlist.list.2&stock=1', 'Dollar My Pencil 666 wooden lead pencils, pack of 12. Soft writing, easy to sharpen, pure non-toxic lead — ideal for school, office and sketching.', 'stationery', 'Dollar', 'Wood', 'Multicolor', 'Pack of 12', 220.00, 240.00, 200.00, 10.00, 54, 5, 1, 1, 0, 1, 1, NULL, NULL, NULL, 'products/5/main/1fd66679-3362-49d7-bdc6-cb65ebc9410b.webp', '[\"products\\/5\\/gallery\\/214213df-2b53-4921-95fb-96de8cdd483a.webp\",\"products\\/5\\/gallery\\/893eb906-cf6c-4739-ad6c-6d5bc1c4df37.webp\",\"products\\/5\\/gallery\\/3ecbc69f-340c-4dd5-b954-deac9a1d1c6f.webp\"]', '2026-07-03 10:49:07', '2026-07-03 17:30:13'),
(6, '74174491-a5ce-4dfb-a072-58177b436114', 2, 16, NULL, NULL, 'Multi-Purpose Strong Foam Tape', 'multi-purpose-strong-foam-tape-1', 'SKU-6A47ECA9EBA95', 'Multi-Purpose Strong Foam Tape Sponge Double Sided Tapes Acrylic Foam Adhesive Tapes for decorations DIY Photo Fixed Stickers Super Strong White Mounting Tape\r\n\r\nThis Multi-Purpose Strong Foam Tape Sponge Double Sided Tapes Acrylic Foam Adhesive Tapes is perfect for decorations, DIY projects, photo fixing, and more. The super strong white mounting tape ensures a secure hold, while the sponge texture provides added cushioning. This tape is suitable for all ages, making it a versatile addition to your crafting supplies. Use it for party decorations, apron embellishments, or any other creative project you can think of. With its easy-to-use design and reliable hold, this foam tape is a must-have for any DIY enthusiast.', 'Multi-Purpose Strong Foam Tape Sponge Double Sided Tapes Acrylic Foam Adhesive Tapes for decorations DIY Photo Fixed Stickers Super Strong White Mounting Tape', 'other', 'None', 'Foam', 'White', 'Inch', 150.00, 300.00, 150.00, 0.00, 85, 10, 1, 1, 1, 1, 1, NULL, NULL, NULL, 'products/6/main/544315f0-3233-493f-bc89-b5532b792c29.webp', '[\"products\\/6\\/gallery\\/1d67126c-ebe5-41d1-84ff-930a56e06686.webp\"]', '2026-07-03 17:08:57', '2026-07-03 17:26:47'),
(7, 'aa1fe129-9999-4c21-a86e-599f0279329f', 2, 9, NULL, NULL, 'Customize Slim Ballpoint With Name and Logo', 'customize-slim-ballpoint-with-name-and-logo', 'SKU-6A48D0E548616', 'Built-in Clip design for easy carrying, can be clipped in your pocket, book, diary\r\nSoft Built-in rubber tip Compatible with smartphones, tablets, and PCs with touch screen\r\nSprucely crafted to offer a higher level of functionality and efficiency\r\n2-in-1 stylus Pen\r\nStylus + ballpoint pen\r\nThis customizable slim ballpoint pen is the perfect addition to your stationery collection. With the ability to add your own name, this pen is not only functional but also personalized to your liking. Its slim design makes it easy to carry around in your pocket or purse, and the ballpoint tip ensures smooth and consistent writing. Whether you\'re jotting down notes or signing important documents, this pen is a reliable choice. Upgrade your writing game with this customizable slim ballpoint pen', 'This customizable slim ballpoint pen is the perfect addition to your stationery collection. With the ability to add your own name, this pen is not only functional but also personalized to your liking. Its slim design makes it easy to carry around in your pocket or purse, and the ballpoint tip ensures smooth and consistent writing. Whether you\'re jotting down notes or signing important documents, this pen is a reliable choice. Upgrade your writing game with this customizable slim ballpoint pen', 'other', 'None', 'Plastic', 'White', '6 Inches', 300.00, 600.00, 150.00, 100.00, 57, 10, 1, 1, 1, 1, 1, NULL, NULL, NULL, 'products/7/main/3d2d16a2-b11a-4040-950a-d4f6e953e5cd.webp', '[\"products\\/7\\/gallery\\/4946a45f-94f0-44f0-956f-ea8ff13161ee.webp\"]', '2026-07-04 09:22:45', '2026-07-04 09:24:33'),
(8, '081e03f7-14ee-4d37-b25d-14eb0cd1381b', 2, 19, NULL, NULL, 'Scientific Calculator MA-82MS 240 Functions and New Multi Color Calculator', 'scientific-calculator-ma-82ms-240-functions-and-new-multi-color-calculator', 'SKU-6A48D292AEB2C', '🌟 MAAZ MA-82MS-C Highlights\r\nCategory\r\n\r\nHighlight\r\n\r\nDetails\r\n\r\nFunctionality\r\n\r\n240 Essential Functions\r\n\r\nIncludes a comprehensive range of features for mathematics, science, and engineering, such as trigonometry, statistics ($\\text{STAT}$-Data Editor), fractions, logarithms, and coordinate conversions.\r\n\r\nDisplay\r\n\r\n2-Line Display\r\n\r\nShows the input expression (formula) on the top line and the calculation result on the bottom line simultaneously, which significantly aids in error checking and complex equation input.\r\n\r\nUser Experience\r\n\r\n$\\text{S-V.P.A.M.}$ Method\r\n\r\nUtilizes the Super Visually Perfect Algebraic Method for natural and intuitive input of mathematical expressions, including fractions and roots, as they appear in a textbook.\r\n\r\nDesign & Style\r\n\r\nNew Multi-Color Options\r\n\r\nThe MA-82MS-C series stands out with its modern, stylish color options like Pink, Purple, Blue, and Teal, offering a fresh alternative to standard grey calculators.\r\n\r\nTarget Audience\r\n\r\nIdeal for Students & Engineers\r\n\r\nExplicitly marketed as a high-quality, durable, and necessary tool suitable for secondary school, college students, and professionals in engineering computing.\r\n\r\nUtility\r\n\r\nMulti-Replay Function\r\n\r\nAllows users to easily scroll back through calculation history to view, edit, and re-run previous formulas without re-entering the entire calculation.\r\n\r\n🧮 MAAZ MA-82MS-C / MA-82MS Calculator Details\r\nFeature\r\n\r\nSpecification / Detail\r\n\r\nModel\r\n\r\nMA-82MS-C (Colored versions) and MA-82MS (Classic black/dark version)\r\n\r\nFunctions\r\n\r\n240 Functions (Comprehensive scientific, trigonometric, logarithmic, and statistical functions)\r\n\r\nDisplay\r\n\r\n2-Line Display (Shows expression and result simultaneously)\r\n\r\nDigits\r\n\r\n$10 + 2$ digits (10-digit mantissa, 2-digit exponent)\r\n\r\nColor Options\r\n\r\nMulti-Color: Pink, Purple, Blue, Teal/Green, and classic Black/Grey.\r\n\r\nPower Source\r\n\r\nBattery operated (often specified as LR 44-Size Battery). Some listings mention Dual Power (Battery and Solar) for similar models, but the images clearly show a battery icon.\r\n\r\nKey Functions\r\n\r\nS-V.P.A.M. (Super Visually Perfect Algebraic Method) for natural input. Includes:\r\n\r\n\r\n* Trigonometric/Inverse Trig ($\\sin$, $\\cos$, $\\tan$)\r\n\r\n\r\n* Hyperbolic/Inverse Hyp ($\\text{hyp}$)\r\n\r\n\r\n* Logarithmic/Exponential ($\\log$, $\\ln$, $10^x$, $e^x$)\r\n\r\n\r\n* Fractions ($\\text{a b/c}$ key)\r\n\r\n\r\n* Coordinate Conversion ($\\text{Pol}$, $\\text{Rec}$)\r\n\r\n\r\n* Statistics ($\\text{S-SUM}$, $\\text{S-VAR}$, STAT-Data Editor)\r\n\r\n\r\n* Permutation & Combination ($\\text{nPr}$, $\\text{nCr}$)\r\n\r\n\r\n* Replay Function (for reviewing and correcting previous calculations)\r\n\r\nTarget User\r\n\r\nSuitable for Students (high quality, for algebra, calculus, physics) and Engineering Computing.', '🌟 MAAZ MA-82MS-C Highlights\r\nCategory\r\n\r\nHighlight\r\n\r\nDetails\r\n\r\nFunctionality\r\n\r\n\r\n\r\nDisplay\r\n\r\n2-Line Display\r\n\r\nShows the input expression (formula) on the top line and the calculation result on the bottom line simultaneously, which significantly aids in error checking and complex equation input.', 'other', 'None', 'Plastic', 'Any', '6 Inches', 400.03, 1200.00, 399.00, 0.26, 69, 10, 1, 1, 1, 1, 1, NULL, NULL, NULL, 'products/8/main/50a037fa-b812-44ba-8c2f-b56bc945f401.webp', '[\"products\\/8\\/gallery\\/44cda628-6a8a-4ade-ae5b-c2a1ff827b65.webp\"]', '2026-07-04 09:29:54', '2026-07-04 09:30:23');
